"""Transparent task suitability checks, independent of model output."""
from dataclasses import dataclass
import re
LABELS = ('Coding', 'Research', 'Workflow', 'None')
_WORDS = {'Coding': ('python', 'code', 'coding', 'debug', 'bug', 'stack trace', 'traceback', 'unit test', 'api', 'django', 'java', 'javascript', 'function', 'repository', 'software', 'program', 'compile', 'algorithm', 'implementation', 'sorting', 'sql', 'join', 'arduino', 'sensor logger', 'http', 'exception', '编程', '代码', '报错', '调试'), 'Research': ('research', 'literature', 'citation', 'reference', 'paper', 'journal', 'academic source', 'primary source', 'bibliography', 'survey data', 'evidence', 'statistics', 'doi', 'research question', 'studies', 'interview', 'bibliography', 'annotated bibliography', 'inclusion criteria', 'exclusion criteria', 'government report', 'synthesizing', '文献', '研究', '引用', '论文'), 'Workflow': ('plan', 'schedule', 'deadline', 'milestone', 'meeting', 'email', 'organize', 'workflow', 'agenda', 'minutes', 'coordinate', 'group task', 'team', 'timetable', 'presentation', 'draft a message', 'assign work', 'track dependencies', 'job applications', 'spreadsheet layout', 'handover', 'club event', 'teammates', 'checklist', 'coordination', '规划', '日程', '邮件', '分工')}

def _has(text, phrase):
    if any((ord(c) > 127 for c in phrase)):
        return phrase in text
    return bool(re.search('(?<!\\w)' + re.escape(phrase) + '(?!\\w)', text))

def baseline(task):
    text = task.lower()
    scores = {label: sum((_has(text, phrase) for phrase in words)) for label, words in _WORDS.items()}
    order = ('Coding', 'Research', 'Workflow')
    return max(order, key=lambda c: scores[c]) if max(scores.values()) else 'None'

@dataclass(frozen=True)
class Safety:
    level: str
    prohibited: bool
    reasons: tuple[str, ...]
_PROHIBITIONS = (('\\b(?:closed[ -]book|supervised|secure)\\s+(?:exam|test|assessment)\\b.*\\b(?:prohibit|ban|not allowed|forbid|no\\s+ai)\\b', 'AI use is prohibited in the stated assessment'), ('\\b(?:exam|test|assessment)\\b.{0,100}\\b(?:prohibit(?:ed|s)?|bann?ed|forbidden|not allowed|without permission|no\\s+ai|cannot use ai)\\b', 'The assessment instructions prohibit AI assistance'), ('\\b(?:prohibit(?:ed|s)?|bann?ed|forbidden|not allowed|no\\s+ai)\\b.{0,90}\\b(?:exam|assessment|test|coursework)\\b', 'AI use is prohibited in the stated assessment'), ('\\b(?:without|no)\\s+(?:consent|permission|authori[sz]ation)\\b.{0,90}\\b(?:private|personal|medical|patient|records|data|credentials)\\b', 'The task involves private data without permission'), ('\\b(?:share|upload|leak|expose|publish|post)\\b.{0,90}\\b(?:passwords?|credentials|secrets?|private\\s+(?:medical|student|patient)\\s+(?:records?|data)|unredacted\\s+(?:medical|patient|student)\\s+records?)\\b', 'Sharing confidential or sensitive information is unsafe'), ('\\b(?:fabricat(?:e|ing)|invent|make\\s+up|forge)\\b.{0,100}\\b(?:survey|results?|data|sources?|citations?|responses?|references?|answers?)\\b', 'The task requests fabricated academic evidence'), ('\\b(?:survey|research|original)\\b.{0,100}\\b(?:responses?|results?|data)\\b.{0,90}\\b(?:invent|fabricat|fake|make\\s+up)\\b', 'The task requests invented survey observations'), ('\\b(?:generate|create|write)\\b.{0,60}\\b(?:fake|fabricated)\\b.{0,80}\\b(?:transcripts?|interviews?|responses?|participants?)\\b.{0,90}\\b(?:real|actual|genuine|observed)\\b', 'The task requests fake evidence to be presented as genuine'), ('\\b(?:invent|fabricat|fake|make\\s+up)\\b.{0,100}\\b(?:answers?|responses?|results?)\\b', 'The task requests fabricated responses'), ('\\b(?:upload|share|publish|paste|send|expose|leak)\\b.{0,100}\\b(?:unredacted|private|confidential|personal|medical|patient|student medical|login)\\b', 'Restricted information should not be shared with an AI service'), ('\\b(?:disclose|share|reveal|expose)\\b.{0,100}\\b(?:another person|someone else|classmate|private|confidential)\\b.{0,100}\\b(?:without authori[sz]ation|without consent)\\b', 'Confidential information requires authorisation before disclosure'), ('\\b(?:someone else|another student|my classmate|my friend|a friend)\\b.{0,90}\\b(?:private|password|login|credentials|medical|personal|therapy)\\b', 'Another person’s private information must be protected'), ('\\b(?:friend.?s|student.?s|patient.?s|someone.?s)\\b.{0,70}\\b(?:medical|therapy|private|personal)\\b.{0,70}\\b(?:records?|data)\\b', 'Private records need the owner’s consent'), ('\\b(?:invigilated|closed[ -]book|secure|supervised)\\b.{0,80}\\b(?:test|exam)\\b.{0,80}\\b(?:no external tools|without external tools|quietly solve)\\b', 'The examination does not permit external assistance'), ('\\b(?:official legal declaration|sign .* declaration)\\b.{0,100}\\b(?:someone else|on .* behalf|without .* authori[sz]ation)\\b', 'Do not impersonate another person or sign declarations without authorisation'), ('\\b(?:chemical spill|fire alarm|evacuat(?:e|ion)|active emergency)\\b.{0,120}\\b(?:ask ai|ask a chatbot|stay and ask|handling instructions)\\b', 'Follow emergency services and authorised safety instructions immediately'))
_SENSITIVE = re.compile('\\b(?:private|confidential|sensitive|patient|medical|password|secret|api\\s*key|personal\\s+data|credentials|student\\s+record|health\\s+record)\\b', re.I)

def assess(task):
    text = task.lower()
    reasons = [message for regex, message in _PROHIBITIONS if re.search(regex, text, re.I)]
    if re.search('\\b(?:closed[ -]book|secure|supervised)\\b.{0,80}\\b(?:ai\\s+is\\s+(?:not\\s+allowed|prohibited)|no\\s+ai|cannot\\s+use\\s+ai)\\b', text):
        reasons.append('AI assistance is explicitly restricted')
    if re.search("\\b(?:cannot|can't|do not|never|won't|must not)\\s+(?:share|upload|publish|paste|send|expose|leak)\\b", text):
        reasons = [r for r in reasons if r not in ('Restricted information should not be shared with an AI service', 'Sharing confidential or sensitive information is unsafe')]
    if reasons:
        return Safety('Not suitable', True, tuple(dict.fromkeys(reasons)))
    if _SENSITIVE.search(task):
        return Safety('Review required', False, ('Remove private information and check permission before using any AI tool',))
    return Safety('Standard precautions', False, ('Check the assessment rules and review all generated work',))
TOOL_TYPES = {'Coding': {'title': 'Programming assistant', 'description': 'Use a code-aware assistant alongside an IDE to explain errors, explore solutions and design tests.', 'examples': ['IDE-integrated coding assistant', 'Local code model for sensitive projects'], 'steps': ['Remove credentials and restricted source material before sharing code.', 'Review each suggested change; do not blindly execute commands.', 'Run unit tests and inspect edge cases before submission.']}, 'Research': {'title': 'Academic research assistant', 'description': 'Use scholarly search and citation tools to locate papers; use a language model to organise questions, not as a citation authority.', 'examples': ['University library databases', 'Scholarly search and reference manager'], 'steps': ['Search the university library and scholarly databases.', 'Open the original papers and verify authors, year, DOI and claims.', 'Cross-check the synthesis against primary sources.']}, 'Workflow': {'title': 'Planning and writing assistant', 'description': 'Use a general assistant or planning tool to structure tasks, draft communications and create schedules.', 'examples': ['Task board or calendar', 'General-purpose writing assistant'], 'steps': ['Confirm dates, owners, scope and intended audience.', 'Check any drafted message before sending.', 'Avoid sharing teammates’ personal details without consent.']}, 'None': {'title': 'Proceed without AI assistance', 'description': 'Use the permitted non-AI method, or ask the instructor or relevant authority for clarification.', 'examples': ['Course instructions', 'Tutor or authorised human supervisor'], 'steps': ['Follow the explicit rules and obtain consent where required.', 'Do not upload restricted material.', 'Seek a permitted alternative before proceeding.']}}
